C342_R = [('    if ((px - ax) * (qx - ax) >= 0) return false;\n    const z = pz + (qz - pz) * (ax - px) / (qx - px);\n    return z >= Math.min(az, bz) && z <= Math.max(az, bz);\n  }', '    if (ax !== bx) {                          // c342: 대각선 벽 — 일반 선분 교차 (전엔 세로 벽으로 잘못 봐서 복도 안에 안 보이는 세로 벽이 생겼다)\n      const ex = bx - ax, ez = bz - az, d1 = ex * (pz - az) - ez * (px - ax), d2 = ex * (qz - az) - ez * (qx - ax);\n      if (d1 * d2 >= 0) return false;\n      const fx = qx - px, fz = qz - pz, d3 = fx * (az - pz) - fz * (ax - px), d4 = fx * (bz - pz) - fz * (bx - px);\n      return d3 * d4 <= 0;\n    }\n    if ((px - ax) * (qx - ax) >= 0) return false;\n    const z = pz + (qz - pz) * (ax - px) / (qx - px);\n    return z >= Math.min(az, bz) && z <= Math.max(az, bz);\n  }')]
